insert into public.episodes (id, title, manifest_version, published_manifest, published_at) values ('ep1', 'Giants on the Horizon', 1, '{"episodeId":"ep1","manifestVersion":1,"title":"Giants on the Horizon","scenes":[{"id":"s01-departure","type":"opening","order":1,"title":"Riding out at dawn","part":"warmup","durationSec":58,"required":true,"prerequisites":[],"checkpoint":"CP1","forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VII","lines":[{"id":"s01-departure-01","speaker":"sancho","text":"Ahead of you, a sleeping village under a gray dawn. Two riders slip out past the last houses: a tall, thin knight on a bony horse, and me, on my donkey.","audioUrl":"/audio/ep1/s01-departure-01.m4a","durationSec":10.75},{"id":"s01-departure-02","speaker":"quixote","text":"Softly, Sancho. Great deeds begin in silence, before the neighbors wake up and ask questions.","audioUrl":"/audio/ep1/s01-departure-02.m4a","durationSec":6.29},{"id":"s01-departure-03","speaker":"sancho","text":"Before my wife wakes up, he means. No goodbyes, no note. Just saddlebags and a wine-skin and a lot of hope.","audioUrl":"/audio/ep1/s01-departure-03.m4a","durationSec":8.32},{"id":"s01-departure-04","speaker":"quixote","text":"Ah, our new companion has joined us! I name you my second squire: Sancho is first, you are second, and in knighthood, ranks matter greatly.","audioUrl":"/audio/ep1/s01-departure-04.m4a","durationSec":9.55},{"id":"s01-departure-05","speaker":"sancho","text":"Ranks. Friend, there are two of us. Second squire is also the last squire.","audioUrl":"/audio/ep1/s01-departure-05.m4a","durationSec":6.01},{"id":"s01-departure-06","speaker":"quixote","text":"Every great order begins small. Forward, Rocinante! The world is full of wrongs, and not one of them knows we are coming.","audioUrl":"/audio/ep1/s01-departure-06.m4a","durationSec":7.51},{"id":"s01-departure-07","speaker":"sancho","text":"Good, let''s keep it that way. Stay beside me, friend; I packed for two, but I can share.","audioUrl":"/audio/ep1/s01-departure-07.m4a","durationSec":6.99}],"bridge":{"id":"s01-departure-bridge","speaker":"sancho","text":"We ride on through the fields; I''ll call you when my master starts making promises.","audioUrl":"/audio/ep1/s01-departure-bridge.m4a","durationSec":5.23}},{"id":"s02-island","type":"optional","order":2,"title":"The promised island","part":"warmup","durationSec":55,"required":false,"prerequisites":["s01-departure"],"checkpoint":null,"forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VII","lines":[{"id":"s02-island-01","speaker":"sancho","text":"The sun climbs over the fields beside you. My master rides with his chin high, the way he does right before he promises something enormous.","audioUrl":"/audio/ep1/s02-island-01.m4a","durationSec":8.73},{"id":"s02-island-02","speaker":"quixote","text":"Sancho, faithful squire. When I win a kingdom, and I will, I shall make you governor of an island.","audioUrl":"/audio/ep1/s02-island-02.m4a","durationSec":6.31},{"id":"s02-island-03","speaker":"sancho","text":"The island again. Friend, he''s promised me this island all night, and I''ve never even seen one, so I''m not sure what you do with it.","audioUrl":"/audio/ep1/s02-island-03.m4a","durationSec":8.65},{"id":"s02-island-04","speaker":"quixote","text":"You rule it, Sancho. Wisely and well.","audioUrl":"/audio/ep1/s02-island-04.m4a","durationSec":2.82},{"id":"s02-island-05","speaker":"sancho","text":"So if I''m a governor, my wife would be... a queen?","audioUrl":"/audio/ep1/s02-island-05.m4a","durationSec":3.37},{"id":"s02-island-06","speaker":"quixote","text":"Naturally. And your children, princes.","audioUrl":"/audio/ep1/s02-island-06.m4a","durationSec":2.8},{"id":"s02-island-07","speaker":"sancho","text":"Master, you''ve met my wife. She''d be a fine queen for one afternoon. Then she''d tell the whole court to wipe their boots.","audioUrl":"/audio/ep1/s02-island-07.m4a","durationSec":8.03},{"id":"s02-island-08","speaker":"quixote","text":"Then a countess, perhaps. Leave it in God''s hands.","audioUrl":"/audio/ep1/s02-island-08.m4a","durationSec":3.56},{"id":"s02-island-09","speaker":"sancho","text":"A countess. Hear that, friend? You''re riding with royalty, future royalty, very far future.","audioUrl":"/audio/ep1/s02-island-09.m4a","durationSec":7.47}],"bridge":{"id":"s02-island-bridge","speaker":"sancho","text":"We''ll ride a while in peace. I''ll call you when I get hungry, which is soon.","audioUrl":"/audio/ep1/s02-island-bridge.m4a","durationSec":4.94}},{"id":"s03-saddlebags","type":"optional","order":3,"title":"What is in the saddlebags","part":"warmup","durationSec":38,"required":false,"prerequisites":["s01-departure"],"checkpoint":null,"forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VII","lines":[{"id":"s03-saddlebags-01","speaker":"sancho","text":"The road bends toward the plain of Montiel. Behind me the saddlebags bounce, and the wine-skin sloshes with every step my donkey takes.","audioUrl":"/audio/ep1/s03-saddlebags-01.m4a","durationSec":8.81},{"id":"s03-saddlebags-02","speaker":"quixote","text":"Sancho. What is that sound?","audioUrl":"/audio/ep1/s03-saddlebags-02.m4a","durationSec":2.08},{"id":"s03-saddlebags-03","speaker":"sancho","text":"Breakfast, master. I brought bread, one small loaf, for emergencies.","audioUrl":"/audio/ep1/s03-saddlebags-03.m4a","durationSec":5.6},{"id":"s03-saddlebags-04","speaker":"quixote","text":"Knights errant do not eat on the road. They live on glory.","audioUrl":"/audio/ep1/s03-saddlebags-04.m4a","durationSec":3.14},{"id":"s03-saddlebags-05","speaker":"sancho","text":"Then you won''t mind if I eat your half.","audioUrl":"/audio/ep1/s03-saddlebags-05.m4a","durationSec":2.54},{"id":"s03-saddlebags-06","speaker":"quixote","text":"Eat, then. But your stomach will never be sung about in ballads.","audioUrl":"/audio/ep1/s03-saddlebags-06.m4a","durationSec":3.85},{"id":"s03-saddlebags-07","speaker":"sancho","text":"My stomach doesn''t want a ballad, it wants bread. Friend, if we pass a bakery, say nothing, or he''ll call it a castle and try to rescue it.","audioUrl":"/audio/ep1/s03-saddlebags-07.m4a","durationSec":9.98}],"bridge":{"id":"s03-saddlebags-bridge","speaker":"sancho","text":"The road runs on toward Montiel; I''ll call you when the land opens wide.","audioUrl":"/audio/ep1/s03-saddlebags-bridge.m4a","durationSec":4.83}},{"id":"s04-plain","type":"core","order":4,"title":"The plain of Montiel","part":"rising","durationSec":46,"required":true,"prerequisites":["s01-departure"],"checkpoint":null,"forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VII","lines":[{"id":"s04-plain-01","speaker":"sancho","text":"The fields fall away, and the plain of Montiel opens around you, flat and gold to the edge of the sky. The sun is up now, and heat shimmers off the road.","audioUrl":"/audio/ep1/s04-plain-01.m4a","durationSec":9.79},{"id":"s04-plain-02","speaker":"quixote","text":"Do you feel it, Sancho? This is the very plain where my adventures were meant to begin.","audioUrl":"/audio/ep1/s04-plain-02.m4a","durationSec":5.27},{"id":"s04-plain-03","speaker":"sancho","text":"I feel the sun on the back of my neck. Is that the adventure?","audioUrl":"/audio/ep1/s04-plain-03.m4a","durationSec":4.11},{"id":"s04-plain-04","speaker":"quixote","text":"Hush. Somewhere out there, a wrong waits to be righted: a giant, a wicked knight, a dragon if we are lucky.","audioUrl":"/audio/ep1/s04-plain-04.m4a","durationSec":7.03},{"id":"s04-plain-05","speaker":"sancho","text":"Or nothing. Flat ground is mostly nothing, master. That''s why it''s flat.","audioUrl":"/audio/ep1/s04-plain-05.m4a","durationSec":5.52},{"id":"s04-plain-06","speaker":"quixote","text":"Nothing is only an adventure that has not arrived yet.","audioUrl":"/audio/ep1/s04-plain-06.m4a","durationSec":2.93},{"id":"s04-plain-07","speaker":"sancho","text":"Friend, remember that one for his tombstone. Meanwhile I''m down to half a loaf, and I''m guarding it like a castle under siege.","audioUrl":"/audio/ep1/s04-plain-07.m4a","durationSec":8.62}],"bridge":{"id":"s04-plain-bridge","speaker":"sancho","text":"Stay beside me, friend. I''ll call you when something shows up on the horizon.","audioUrl":"/audio/ep1/s04-plain-bridge.m4a","durationSec":5.58}},{"id":"s05-windmills-sighted","type":"core","order":5,"title":"Giants on the horizon","part":"rising","durationSec":62,"required":true,"prerequisites":["s04-plain"],"checkpoint":"CP2","forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"s05-windmills-sighted-01","speaker":"sancho","text":"Friend. Look at the ridge ahead of you. Thirty or forty windmills, tall as churches, their big wooden sails turning slowly against the sky.","audioUrl":"/audio/ep1/s05-windmills-sighted-01.m4a","durationSec":9.55},{"id":"s05-windmills-sighted-02","speaker":"sancho","text":"Perfectly normal countryside. Except my master has just seen them.","audioUrl":"/audio/ep1/s05-windmills-sighted-02.m4a","durationSec":5.16},{"id":"s05-windmills-sighted-03","speaker":"quixote","text":"Sancho.","audioUrl":"/audio/ep1/s05-windmills-sighted-03.m4a","durationSec":0.71},{"id":"s05-windmills-sighted-04","speaker":"sancho","text":"Oh, no.","audioUrl":"/audio/ep1/s05-windmills-sighted-04.m4a","durationSec":1.2},{"id":"s05-windmills-sighted-05","speaker":"quixote","text":"Do you see them?","audioUrl":"/audio/ep1/s05-windmills-sighted-05.m4a","durationSec":0.94},{"id":"s05-windmills-sighted-06","speaker":"sancho","text":"Yes.","audioUrl":"/audio/ep1/s05-windmills-sighted-06.m4a","durationSec":0.81},{"id":"s05-windmills-sighted-07","speaker":"quixote","text":"Giants.","audioUrl":"/audio/ep1/s05-windmills-sighted-07.m4a","durationSec":0.73},{"id":"s05-windmills-sighted-08","speaker":"sancho","text":"Windmills.","audioUrl":"/audio/ep1/s05-windmills-sighted-08.m4a","durationSec":1.09},{"id":"s05-windmills-sighted-09","speaker":"quixote","text":"Thirty giants! Maybe forty, maybe a thousand, I did not count, and every one with arms two leagues long!","audioUrl":"/audio/ep1/s05-windmills-sighted-09.m4a","durationSec":7.28},{"id":"s05-windmills-sighted-10","speaker":"sancho","text":"Master, those are sails. The wind turns them, and they grind flour for bread. You like bread.","audioUrl":"/audio/ep1/s05-windmills-sighted-10.m4a","durationSec":6.93},{"id":"s05-windmills-sighted-11","speaker":"quixote","text":"Bread? Destiny stands on that ridge, and you speak to me of bread?","audioUrl":"/audio/ep1/s05-windmills-sighted-11.m4a","durationSec":4.11},{"id":"s05-windmills-sighted-12","speaker":"sancho","text":"It is very good bread. Friend, that ridge is more bread than I have seen in my whole life.","audioUrl":"/audio/ep1/s05-windmills-sighted-12.m4a","durationSec":6.03},{"id":"s05-windmills-sighted-13","speaker":"quixote","text":"Fortune is arranging our affairs better than we could have wished. This is righteous war, Sancho.","audioUrl":"/audio/ep1/s05-windmills-sighted-13.m4a","durationSec":5.73},{"id":"s05-windmills-sighted-14","speaker":"sancho","text":"So, he says giants, I say windmills. Friend, you have the deciding vote, and I know which way you''re leaning.","audioUrl":"/audio/ep1/s05-windmills-sighted-14.m4a","durationSec":7.76}],"bridge":{"id":"s05-windmills-sighted-bridge","speaker":"sancho","text":"Stay close, friend. He''s sizing them up; I''ll call you when he picks one.","audioUrl":"/audio/ep1/s05-windmills-sighted-bridge.m4a","durationSec":5.77}},{"id":"s06-the-one-on-the-left","type":"optional","order":6,"title":"The one on the left","part":"rising","durationSec":46,"required":false,"prerequisites":["s05-windmills-sighted"],"checkpoint":null,"forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"s06-the-one-on-the-left-01","speaker":"sancho","text":"The windmills are closer now. You can hear them creak, a long wooden groan, and each sail''s shadow sweeps across the road like the hand of a clock.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-01.m4a","durationSec":9.17},{"id":"s06-the-one-on-the-left-02","speaker":"quixote","text":"Sancho. The one on the left.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-02.m4a","durationSec":2.02},{"id":"s06-the-one-on-the-left-03","speaker":"sancho","text":"The windmill?","audioUrl":"/audio/ep1/s06-the-one-on-the-left-03.m4a","durationSec":1.07},{"id":"s06-the-one-on-the-left-04","speaker":"quixote","text":"The giant. He has been watching us.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-04.m4a","durationSec":2.32},{"id":"s06-the-one-on-the-left-05","speaker":"sancho","text":"He has no eyes.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-05.m4a","durationSec":1.49},{"id":"s06-the-one-on-the-left-06","speaker":"quixote","text":"Precisely... A professional.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-06.m4a","durationSec":1.88},{"id":"s06-the-one-on-the-left-07","speaker":"sancho","text":"Friend, are you still with me? Good. One of us should be.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-07.m4a","durationSec":4.46},{"id":"s06-the-one-on-the-left-08","speaker":"quixote","text":"Look! He waves his arms. He is challenging me.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-08.m4a","durationSec":3.46},{"id":"s06-the-one-on-the-left-09","speaker":"sancho","text":"That''s the wind, master.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-09.m4a","durationSec":1.9},{"id":"s06-the-one-on-the-left-10","speaker":"quixote","text":"And why is the wind blowing?","audioUrl":"/audio/ep1/s06-the-one-on-the-left-10.m4a","durationSec":1.42},{"id":"s06-the-one-on-the-left-11","speaker":"sancho","text":"Because... huh. Actually, I don''t know.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-11.m4a","durationSec":3.61},{"id":"s06-the-one-on-the-left-12","speaker":"quixote","text":"Ha! Even you admit there is a mystery.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-12.m4a","durationSec":2.5},{"id":"s06-the-one-on-the-left-13","speaker":"sancho","text":"He won... he actually won one. Friend, never tell him; I need a bite of bread to recover.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-13.m4a","durationSec":6.88}],"bridge":{"id":"s06-the-one-on-the-left-bridge","speaker":"sancho","text":"I have one more question for him; I''ll call you before he does anything expensive.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-bridge.m4a","durationSec":5.31}},{"id":"s07-who-pays","type":"optional","order":7,"title":"Who pays for a windmill","part":"rising","durationSec":38,"required":false,"prerequisites":["s05-windmills-sighted"],"checkpoint":null,"forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"s07-who-pays-01","speaker":"sancho","text":"Ahead of you the sails turn and turn. My master is polishing his lance with his sleeve, and that is never a good sign.","audioUrl":"/audio/ep1/s07-who-pays-01.m4a","durationSec":7.74},{"id":"s07-who-pays-02","speaker":"sancho","text":"Master, before you attack. If you knock one down, who pays for the windmill?","audioUrl":"/audio/ep1/s07-who-pays-02.m4a","durationSec":5.45},{"id":"s07-who-pays-03","speaker":"quixote","text":"The king.","audioUrl":"/audio/ep1/s07-who-pays-03.m4a","durationSec":0.57},{"id":"s07-who-pays-04","speaker":"sancho","text":"Which king?","audioUrl":"/audio/ep1/s07-who-pays-04.m4a","durationSec":1.05},{"id":"s07-who-pays-05","speaker":"quixote","text":"We will discuss that after the battle.","audioUrl":"/audio/ep1/s07-who-pays-05.m4a","durationSec":1.95},{"id":"s07-who-pays-06","speaker":"sancho","text":"And the flour? That mill grinds bread for half the valley. Knock it down and everyone eats soup.","audioUrl":"/audio/ep1/s07-who-pays-06.m4a","durationSec":6.43},{"id":"s07-who-pays-07","speaker":"quixote","text":"Then the giant has stolen their bread, and I shall win it back for them.","audioUrl":"/audio/ep1/s07-who-pays-07.m4a","durationSec":3.75},{"id":"s07-who-pays-08","speaker":"sancho","text":"Hm, that almost made sense. Friend, for half a second I agreed with him. Please don''t let it happen again.","audioUrl":"/audio/ep1/s07-who-pays-08.m4a","durationSec":8.33}],"bridge":{"id":"s07-who-pays-bridge","speaker":"sancho","text":"He''s gathering up his reins. Stay beside me, friend; I''ll call you when he''s ready.","audioUrl":"/audio/ep1/s07-who-pays-bridge.m4a","durationSec":6.14}},{"id":"s08-lance-in-rest","type":"core","order":8,"title":"Lance in rest","part":"rising","durationSec":55,"required":true,"prerequisites":["s05-windmills-sighted"],"checkpoint":"CP3","forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"s08-lance-in-rest-01","speaker":"sancho","text":"You are facing the windmills now. My master sits tall on Rocinante, his buckler braced on his arm, his lance in rest, pointed at the nearest sail.","audioUrl":"/audio/ep1/s08-lance-in-rest-01.m4a","durationSec":9.9},{"id":"s08-lance-in-rest-02","speaker":"quixote","text":"If you are afraid, Sancho, go aside and say your prayers, while I meet them in fierce and unequal combat.","audioUrl":"/audio/ep1/s08-lance-in-rest-02.m4a","durationSec":6.52},{"id":"s08-lance-in-rest-03","speaker":"sancho","text":"I''m not afraid, I''m right, and that''s different. Friend, back me up here.","audioUrl":"/audio/ep1/s08-lance-in-rest-03.m4a","durationSec":5.52},{"id":"s08-lance-in-rest-04","speaker":"quixote","text":"Do not flee, you cowards! It is one knight alone who comes against you.","audioUrl":"/audio/ep1/s08-lance-in-rest-04.m4a","durationSec":4.73},{"id":"s08-lance-in-rest-05","speaker":"sancho","text":"Nobody is fleeing, master. They''re bolted to the ground.","audioUrl":"/audio/ep1/s08-lance-in-rest-05.m4a","durationSec":4.17},{"id":"s08-lance-in-rest-06","speaker":"quixote","text":"Lady Dulcinea, flower of beauty, I commend myself to you. Stand by me in this peril.","audioUrl":"/audio/ep1/s08-lance-in-rest-06.m4a","durationSec":5.98},{"id":"s08-lance-in-rest-07","speaker":"sancho","text":"He''s talking to his lady. She''s far away in Toboso, but he says she hears every word.","audioUrl":"/audio/ep1/s08-lance-in-rest-07.m4a","durationSec":6.19},{"id":"s08-lance-in-rest-08","speaker":"sancho","text":"Friend, stay with me. Whatever those things are, we watch together. I''m holding the last of the bread, in case anyone needs comfort.","audioUrl":"/audio/ep1/s08-lance-in-rest-08.m4a","durationSec":9.04}],"bridge":{"id":"s08-lance-in-rest-bridge","speaker":"sancho","text":"He''s ready. Stay with me, friend; I''ll call you the moment Rocinante moves.","audioUrl":"/audio/ep1/s08-lance-in-rest-bridge.m4a","durationSec":5.92}},{"id":"s09-charge","type":"climax","order":9,"title":"The charge","part":"climax","durationSec":50,"required":true,"prerequisites":["s08-lance-in-rest"],"checkpoint":null,"forCheckpoint":null,"beat":"charge","source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"s09-charge-01","speaker":"sancho","text":"Ahead of you, my master spurs Rocinante, and the old horse lowers his head and heads straight for the nearest windmill.","audioUrl":"/audio/ep1/s09-charge-01.m4a","durationSec":7.26},{"id":"s09-charge-02","speaker":"sancho","text":"Rocinante breaks into a gallop. Ride with him if your legs feel good, or stay right here beside me. Either way, we see it together.","audioUrl":"/audio/ep1/s09-charge-02.m4a","durationSec":9.12},{"id":"s09-charge-03","speaker":"quixote","text":"Wave all the arms you like, giant! For Dulcinea! You shall answer to me!","audioUrl":"/audio/ep1/s09-charge-03.m4a","durationSec":4.81},{"id":"s09-charge-04","speaker":"sancho","text":"Master, it''s a windmill! It''s a windmill!","audioUrl":"/audio/ep1/s09-charge-04.m4a","durationSec":3.18},{"id":"s09-charge-05","speaker":"sancho","text":"Just then the wind picks up. The great sail swings down, and the lance goes straight into it.","audioUrl":"/audio/ep1/s09-charge-05.m4a","durationSec":6.14},{"id":"s09-charge-06","speaker":"sancho","text":"Crack. The lance shatters into pieces. The sail sweeps horse and rider up and drops them, rolling over and over across the plain.","audioUrl":"/audio/ep1/s09-charge-06.m4a","durationSec":8.73},{"id":"s09-charge-07","speaker":"quixote","text":"A worthy opponent...","audioUrl":"/audio/ep1/s09-charge-07.m4a","durationSec":1.08},{"id":"s09-charge-08","speaker":"sancho","text":"Hold on, master, I''m coming! Friend, come with me. That was the expensive part.","audioUrl":"/audio/ep1/s09-charge-08.m4a","durationSec":6.7}],"bridge":null},{"id":"s10-aftermath","type":"ending","order":10,"title":"Freston the enchanter","part":"epilogue","durationSec":46,"required":true,"prerequisites":["s09-charge"],"checkpoint":null,"forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"s10-aftermath-01","speaker":"sancho","text":"Dust settles around you. My master lies flat beside Rocinante, and I come bouncing up on my donkey.","audioUrl":"/audio/ep1/s10-aftermath-01.m4a","durationSec":7.47},{"id":"s10-aftermath-02","speaker":"sancho","text":"God help us, master. Didn''t I tell you they were windmills? Nobody could miss it, unless he had windmills in his head.","audioUrl":"/audio/ep1/s10-aftermath-02.m4a","durationSec":8.01},{"id":"s10-aftermath-03","speaker":"quixote","text":"Hush, friend Sancho. The sage Freston turned the giants into mills, to rob me of the glory of defeating them.","audioUrl":"/audio/ep1/s10-aftermath-03.m4a","durationSec":7},{"id":"s10-aftermath-04","speaker":"sancho","text":"Of course. Freston. The enchanter nobody has ever seen.","audioUrl":"/audio/ep1/s10-aftermath-04.m4a","durationSec":4.7},{"id":"s10-aftermath-05","speaker":"quixote","text":"His arts will fail in the end. Help me up; we ride for Puerto Lapice, where adventures are thick on the road.","audioUrl":"/audio/ep1/s10-aftermath-05.m4a","durationSec":6.68},{"id":"s10-aftermath-06","speaker":"sancho","text":"And bread, I hope. Friend, from now on I only eat bread that was never a giant. Thank you for riding with us, second squire, go well.","audioUrl":"/audio/ep1/s10-aftermath-06.m4a","durationSec":10.08}],"bridge":null},{"id":"e01-encourage","type":"optional","order":11,"title":"A knight''s companion","part":"rising","durationSec":6,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":null,"beat":"encourage","source":"Ormsby 1885, Part I, ch. VII-VIII","lines":[{"id":"e01-encourage-01","speaker":"quixote","text":"Second squire, a knight is only as brave as the friend who rides beside him. I am glad it is you.","audioUrl":"/audio/ep1/e01-encourage-01.m4a","durationSec":5.9}],"bridge":null},{"id":"e02-encourage","type":"optional","order":12,"title":"Good company","part":"rising","durationSec":9,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":null,"beat":"encourage","source":"Ormsby 1885, Part I, ch. VII-VIII","lines":[{"id":"e02-encourage-01","speaker":"sancho","text":"Friend, between you and me, this is the nicest part of the trip. Open road, good company, and nobody attacking anything.","audioUrl":"/audio/ep1/e02-encourage-01.m4a","durationSec":8.73}],"bridge":null},{"id":"e03-encourage","type":"optional","order":13,"title":"Better shared","part":"rising","durationSec":7,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":null,"beat":"encourage","source":"Ormsby 1885, Part I, ch. VII-VIII","lines":[{"id":"e03-encourage-01","speaker":"quixote","text":"Stay beside me, friend. Every road is better shared.","audioUrl":"/audio/ep1/e03-encourage-01.m4a","durationSec":3.72},{"id":"e03-encourage-02","speaker":"sancho","text":"That''s the wisest thing he''s said all week.","audioUrl":"/audio/ep1/e03-encourage-02.m4a","durationSec":2.67}],"bridge":null},{"id":"e04-encourage","type":"optional","order":14,"title":"Best conversation","part":"rising","durationSec":10,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":null,"beat":"encourage","source":"Ormsby 1885, Part I, ch. VII-VIII","lines":[{"id":"e04-encourage-01","speaker":"sancho","text":"Still with us, friend? Good. My master talks to the sky, my donkey talks to nobody, so you''re the best company on this road.","audioUrl":"/audio/ep1/e04-encourage-01.m4a","durationSec":9.18}],"bridge":null},{"id":"x01-signoff","type":"signoff","order":15,"title":"Until next time","part":"epilogue","durationSec":25,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":null,"beat":null,"source":"Ormsby 1885, Part I, ch. VII-VIII","lines":[{"id":"x01-signoff-01","speaker":"sancho","text":"Heading home, friend? That''s fine, good thinking even. The windmills aren''t going anywhere.","audioUrl":"/audio/ep1/x01-signoff-01.m4a","durationSec":6.75},{"id":"x01-signoff-02","speaker":"quixote","text":"A wise squire knows when the day''s road is done. Our quest will wait, exactly where we leave it.","audioUrl":"/audio/ep1/x01-signoff-02.m4a","durationSec":5.61},{"id":"x01-signoff-03","speaker":"sancho","text":"I''ll save your place, and I''ll save you some bread. Some of the bread. Come back whenever you like.","audioUrl":"/audio/ep1/x01-signoff-03.m4a","durationSec":6.96},{"id":"x01-signoff-04","speaker":"quixote","text":"Farewell for now, second squire. Go in peace; our road will be here.","audioUrl":"/audio/ep1/x01-signoff-04.m4a","durationSec":4.64}],"bridge":null},{"id":"r01-recap-cp1","type":"recap","order":16,"title":"Previously: the departure","part":"warmup","durationSec":28,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":"CP1","beat":null,"source":"Ormsby 1885, Part I, ch. VII","lines":[{"id":"r01-recap-cp1-01","speaker":"quixote","text":"Previously, my second squire, we rode out of the village at dawn to right the wrongs of the world.","audioUrl":"/audio/ep1/r01-recap-cp1-01.m4a","durationSec":5.43},{"id":"r01-recap-cp1-02","speaker":"sancho","text":"And I came along on my donkey, with saddlebags, a wine-skin, and the promise of an island.","audioUrl":"/audio/ep1/r01-recap-cp1-02.m4a","durationSec":6.27},{"id":"r01-recap-cp1-03","speaker":"quixote","text":"No one saw us leave. Not one wrong in all the world suspects we are coming.","audioUrl":"/audio/ep1/r01-recap-cp1-03.m4a","durationSec":4.45},{"id":"r01-recap-cp1-04","speaker":"sancho","text":"Not my wife, either. Friend, welcome back: the road is open, the bread is packed, and my master is already looking for trouble. Stay beside me.","audioUrl":"/audio/ep1/r01-recap-cp1-04.m4a","durationSec":10.54}],"bridge":null},{"id":"r02-recap-cp2","type":"recap","order":17,"title":"Previously: giants sighted","part":"warmup","durationSec":29,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":"CP2","beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"r02-recap-cp2-01","speaker":"quixote","text":"Previously, on the plain of Montiel, we sighted thirty or forty giants on the horizon.","audioUrl":"/audio/ep1/r02-recap-cp2-01.m4a","durationSec":5.28},{"id":"r02-recap-cp2-02","speaker":"sancho","text":"Windmills. He says giants, I say windmills, and they grind flour for bread.","audioUrl":"/audio/ep1/r02-recap-cp2-02.m4a","durationSec":5.89},{"id":"r02-recap-cp2-03","speaker":"quixote","text":"Monstrous giants, with arms two leagues long. Fortune itself has placed them in my path, squire.","audioUrl":"/audio/ep1/r02-recap-cp2-03.m4a","durationSec":6.39},{"id":"r02-recap-cp2-04","speaker":"sancho","text":"Fortune placed them on a ridge, where the wind is. Friend, welcome back: the windmills are right where we left them, still turning, and still not giants.","audioUrl":"/audio/ep1/r02-recap-cp2-04.m4a","durationSec":10.06}],"bridge":null},{"id":"r03-recap-cp3","type":"recap","order":18,"title":"Previously: facing the windmills","part":"warmup","durationSec":28,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":"CP3","beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"r03-recap-cp3-01","speaker":"quixote","text":"Previously, I faced the giants with my lance in rest, and commended myself to my lady Dulcinea.","audioUrl":"/audio/ep1/r03-recap-cp3-01.m4a","durationSec":6.15},{"id":"r03-recap-cp3-02","speaker":"sancho","text":"I told him they were windmills. He told me to go and pray if I was afraid.","audioUrl":"/audio/ep1/r03-recap-cp3-02.m4a","durationSec":5.15},{"id":"r03-recap-cp3-03","speaker":"quixote","text":"A squire''s fear is natural. A knight''s courage is not for sale.","audioUrl":"/audio/ep1/r03-recap-cp3-03.m4a","durationSec":3.74},{"id":"r03-recap-cp3-04","speaker":"sancho","text":"Neither is my bread, and there is very little left. Friend, welcome back: he''s still sitting on Rocinante, still pointing his lance at a windmill. Stay beside me.","audioUrl":"/audio/ep1/r03-recap-cp3-04.m4a","durationSec":11.84}],"bridge":null},{"id":"c01-finish-cp1","type":"compressed_ending","order":19,"title":"The story, quickly, from the departure","part":"epilogue","durationSec":46,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":"CP1","beat":null,"source":"Ormsby 1885, Part I, ch. VII-VIII","lines":[{"id":"c01-finish-cp1-01","speaker":"sancho","text":"Here''s the rest of the story, friend, told quickly. We ride out onto the plain of Montiel, and there on the ridge stand thirty or forty windmills.","audioUrl":"/audio/ep1/c01-finish-cp1-01.m4a","durationSec":9.69},{"id":"c01-finish-cp1-02","speaker":"quixote","text":"Giants, Sancho! Monstrous giants! If you are afraid, go aside and pray.","audioUrl":"/audio/ep1/c01-finish-cp1-02.m4a","durationSec":5.81},{"id":"c01-finish-cp1-03","speaker":"sancho","text":"He commends himself to his lady Dulcinea, lowers his lance, and charges. The wind turns a sail, the lance shatters, and horse and rider roll across the plain.","audioUrl":"/audio/ep1/c01-finish-cp1-03.m4a","durationSec":10.72},{"id":"c01-finish-cp1-04","speaker":"sancho","text":"I rush to help him. Didn''t I tell you they were windmills, master?","audioUrl":"/audio/ep1/c01-finish-cp1-04.m4a","durationSec":4.41},{"id":"c01-finish-cp1-05","speaker":"quixote","text":"The sage Freston turned the giants into mills, to rob me of my glory. On to Puerto Lapice!","audioUrl":"/audio/ep1/c01-finish-cp1-05.m4a","durationSec":5.86},{"id":"c01-finish-cp1-06","speaker":"sancho","text":"So we ride on, one lance lighter, and my bread is still safe. Thank you for riding with us, friend. Go well.","audioUrl":"/audio/ep1/c01-finish-cp1-06.m4a","durationSec":7.98}],"bridge":null},{"id":"c02-finish-cp2","type":"compressed_ending","order":20,"title":"The story, quickly, from the windmills","part":"epilogue","durationSec":47,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":"CP2","beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"c02-finish-cp2-01","speaker":"sancho","text":"Here''s how it ends, friend, told quickly. The windmills turn on the ridge, and my master is certain they are giants.","audioUrl":"/audio/ep1/c02-finish-cp2-01.m4a","durationSec":8.13},{"id":"c02-finish-cp2-02","speaker":"quixote","text":"If you are afraid, Sancho, go aside and say your prayers. I fight them alone.","audioUrl":"/audio/ep1/c02-finish-cp2-02.m4a","durationSec":5.2},{"id":"c02-finish-cp2-03","speaker":"sancho","text":"He commends himself to Dulcinea, braces his buckler, and charges on Rocinante. A sail catches the lance, it shatters, and horse and rider go rolling across the plain.","audioUrl":"/audio/ep1/c02-finish-cp2-03.m4a","durationSec":11.63},{"id":"c02-finish-cp2-04","speaker":"sancho","text":"I come running on my donkey to help him up. I did say windmills.","audioUrl":"/audio/ep1/c02-finish-cp2-04.m4a","durationSec":4.7},{"id":"c02-finish-cp2-05","speaker":"quixote","text":"The enchanter Freston changed them into mills, to steal my glory. His tricks will fail. We ride for Puerto Lapice.","audioUrl":"/audio/ep1/c02-finish-cp2-05.m4a","durationSec":7.46},{"id":"c02-finish-cp2-06","speaker":"sancho","text":"And so we ride on, bruised but cheerful, with a little bread left. Thank you, second squire. Go well.","audioUrl":"/audio/ep1/c02-finish-cp2-06.m4a","durationSec":7.52}],"bridge":null},{"id":"c03-finish-cp3","type":"compressed_ending","order":21,"title":"The story, quickly, from the charge","part":"epilogue","durationSec":42,"required":false,"prerequisites":[],"checkpoint":null,"forCheckpoint":"CP3","beat":null,"source":"Ormsby 1885, Part I, ch. VIII","lines":[{"id":"c03-finish-cp3-01","speaker":"sancho","text":"Here''s how it ends, friend, told quickly. My master spurs Rocinante straight at the nearest windmill, shouting for Dulcinea.","audioUrl":"/audio/ep1/c03-finish-cp3-01.m4a","durationSec":8.99},{"id":"c03-finish-cp3-02","speaker":"sancho","text":"The wind swings a sail down. The lance shatters, and the sail flings horse and rider rolling across the plain.","audioUrl":"/audio/ep1/c03-finish-cp3-02.m4a","durationSec":7.17},{"id":"c03-finish-cp3-03","speaker":"sancho","text":"I come running on my donkey. Master, didn''t I tell you they were windmills?","audioUrl":"/audio/ep1/c03-finish-cp3-03.m4a","durationSec":5.04},{"id":"c03-finish-cp3-04","speaker":"quixote","text":"Hush, Sancho. The sage Freston turned those giants into mills, to rob me of my glory. But his arts will fail against my good sword.","audioUrl":"/audio/ep1/c03-finish-cp3-04.m4a","durationSec":8.64},{"id":"c03-finish-cp3-05","speaker":"sancho","text":"So I help him up, and we ride on toward Puerto Lapice. He''s sore, I''m hungry, and the bread survived. Thank you for riding with us, friend.","audioUrl":"/audio/ep1/c03-finish-cp3-05.m4a","durationSec":10.17}],"bridge":null}]}'::jsonb, now()) on conflict (id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's01-departure', 1, 'opening', 'Riding out at dawn', 'warmup', 58, true, '{}', 'CP1', null, null, 'Ormsby 1885, Part I, ch. VII', '[{"id":"s01-departure-01","speaker":"sancho","text":"Ahead of you, a sleeping village under a gray dawn. Two riders slip out past the last houses: a tall, thin knight on a bony horse, and me, on my donkey.","audioUrl":"/audio/ep1/s01-departure-01.m4a","durationSec":10.75},{"id":"s01-departure-02","speaker":"quixote","text":"Softly, Sancho. Great deeds begin in silence, before the neighbors wake up and ask questions.","audioUrl":"/audio/ep1/s01-departure-02.m4a","durationSec":6.29},{"id":"s01-departure-03","speaker":"sancho","text":"Before my wife wakes up, he means. No goodbyes, no note. Just saddlebags and a wine-skin and a lot of hope.","audioUrl":"/audio/ep1/s01-departure-03.m4a","durationSec":8.32},{"id":"s01-departure-04","speaker":"quixote","text":"Ah, our new companion has joined us! I name you my second squire: Sancho is first, you are second, and in knighthood, ranks matter greatly.","audioUrl":"/audio/ep1/s01-departure-04.m4a","durationSec":9.55},{"id":"s01-departure-05","speaker":"sancho","text":"Ranks. Friend, there are two of us. Second squire is also the last squire.","audioUrl":"/audio/ep1/s01-departure-05.m4a","durationSec":6.01},{"id":"s01-departure-06","speaker":"quixote","text":"Every great order begins small. Forward, Rocinante! The world is full of wrongs, and not one of them knows we are coming.","audioUrl":"/audio/ep1/s01-departure-06.m4a","durationSec":7.51},{"id":"s01-departure-07","speaker":"sancho","text":"Good, let''s keep it that way. Stay beside me, friend; I packed for two, but I can share.","audioUrl":"/audio/ep1/s01-departure-07.m4a","durationSec":6.99}]'::jsonb, '{"id":"s01-departure-bridge","speaker":"sancho","text":"We ride on through the fields; I''ll call you when my master starts making promises.","audioUrl":"/audio/ep1/s01-departure-bridge.m4a","durationSec":5.23}'::jsonb) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's02-island', 2, 'optional', 'The promised island', 'warmup', 55, false, array['s01-departure'], null, null, null, 'Ormsby 1885, Part I, ch. VII', '[{"id":"s02-island-01","speaker":"sancho","text":"The sun climbs over the fields beside you. My master rides with his chin high, the way he does right before he promises something enormous.","audioUrl":"/audio/ep1/s02-island-01.m4a","durationSec":8.73},{"id":"s02-island-02","speaker":"quixote","text":"Sancho, faithful squire. When I win a kingdom, and I will, I shall make you governor of an island.","audioUrl":"/audio/ep1/s02-island-02.m4a","durationSec":6.31},{"id":"s02-island-03","speaker":"sancho","text":"The island again. Friend, he''s promised me this island all night, and I''ve never even seen one, so I''m not sure what you do with it.","audioUrl":"/audio/ep1/s02-island-03.m4a","durationSec":8.65},{"id":"s02-island-04","speaker":"quixote","text":"You rule it, Sancho. Wisely and well.","audioUrl":"/audio/ep1/s02-island-04.m4a","durationSec":2.82},{"id":"s02-island-05","speaker":"sancho","text":"So if I''m a governor, my wife would be... a queen?","audioUrl":"/audio/ep1/s02-island-05.m4a","durationSec":3.37},{"id":"s02-island-06","speaker":"quixote","text":"Naturally. And your children, princes.","audioUrl":"/audio/ep1/s02-island-06.m4a","durationSec":2.8},{"id":"s02-island-07","speaker":"sancho","text":"Master, you''ve met my wife. She''d be a fine queen for one afternoon. Then she''d tell the whole court to wipe their boots.","audioUrl":"/audio/ep1/s02-island-07.m4a","durationSec":8.03},{"id":"s02-island-08","speaker":"quixote","text":"Then a countess, perhaps. Leave it in God''s hands.","audioUrl":"/audio/ep1/s02-island-08.m4a","durationSec":3.56},{"id":"s02-island-09","speaker":"sancho","text":"A countess. Hear that, friend? You''re riding with royalty, future royalty, very far future.","audioUrl":"/audio/ep1/s02-island-09.m4a","durationSec":7.47}]'::jsonb, '{"id":"s02-island-bridge","speaker":"sancho","text":"We''ll ride a while in peace. I''ll call you when I get hungry, which is soon.","audioUrl":"/audio/ep1/s02-island-bridge.m4a","durationSec":4.94}'::jsonb) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's03-saddlebags', 3, 'optional', 'What is in the saddlebags', 'warmup', 38, false, array['s01-departure'], null, null, null, 'Ormsby 1885, Part I, ch. VII', '[{"id":"s03-saddlebags-01","speaker":"sancho","text":"The road bends toward the plain of Montiel. Behind me the saddlebags bounce, and the wine-skin sloshes with every step my donkey takes.","audioUrl":"/audio/ep1/s03-saddlebags-01.m4a","durationSec":8.81},{"id":"s03-saddlebags-02","speaker":"quixote","text":"Sancho. What is that sound?","audioUrl":"/audio/ep1/s03-saddlebags-02.m4a","durationSec":2.08},{"id":"s03-saddlebags-03","speaker":"sancho","text":"Breakfast, master. I brought bread, one small loaf, for emergencies.","audioUrl":"/audio/ep1/s03-saddlebags-03.m4a","durationSec":5.6},{"id":"s03-saddlebags-04","speaker":"quixote","text":"Knights errant do not eat on the road. They live on glory.","audioUrl":"/audio/ep1/s03-saddlebags-04.m4a","durationSec":3.14},{"id":"s03-saddlebags-05","speaker":"sancho","text":"Then you won''t mind if I eat your half.","audioUrl":"/audio/ep1/s03-saddlebags-05.m4a","durationSec":2.54},{"id":"s03-saddlebags-06","speaker":"quixote","text":"Eat, then. But your stomach will never be sung about in ballads.","audioUrl":"/audio/ep1/s03-saddlebags-06.m4a","durationSec":3.85},{"id":"s03-saddlebags-07","speaker":"sancho","text":"My stomach doesn''t want a ballad, it wants bread. Friend, if we pass a bakery, say nothing, or he''ll call it a castle and try to rescue it.","audioUrl":"/audio/ep1/s03-saddlebags-07.m4a","durationSec":9.98}]'::jsonb, '{"id":"s03-saddlebags-bridge","speaker":"sancho","text":"The road runs on toward Montiel; I''ll call you when the land opens wide.","audioUrl":"/audio/ep1/s03-saddlebags-bridge.m4a","durationSec":4.83}'::jsonb) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's04-plain', 4, 'core', 'The plain of Montiel', 'rising', 46, true, array['s01-departure'], null, null, null, 'Ormsby 1885, Part I, ch. VII', '[{"id":"s04-plain-01","speaker":"sancho","text":"The fields fall away, and the plain of Montiel opens around you, flat and gold to the edge of the sky. The sun is up now, and heat shimmers off the road.","audioUrl":"/audio/ep1/s04-plain-01.m4a","durationSec":9.79},{"id":"s04-plain-02","speaker":"quixote","text":"Do you feel it, Sancho? This is the very plain where my adventures were meant to begin.","audioUrl":"/audio/ep1/s04-plain-02.m4a","durationSec":5.27},{"id":"s04-plain-03","speaker":"sancho","text":"I feel the sun on the back of my neck. Is that the adventure?","audioUrl":"/audio/ep1/s04-plain-03.m4a","durationSec":4.11},{"id":"s04-plain-04","speaker":"quixote","text":"Hush. Somewhere out there, a wrong waits to be righted: a giant, a wicked knight, a dragon if we are lucky.","audioUrl":"/audio/ep1/s04-plain-04.m4a","durationSec":7.03},{"id":"s04-plain-05","speaker":"sancho","text":"Or nothing. Flat ground is mostly nothing, master. That''s why it''s flat.","audioUrl":"/audio/ep1/s04-plain-05.m4a","durationSec":5.52},{"id":"s04-plain-06","speaker":"quixote","text":"Nothing is only an adventure that has not arrived yet.","audioUrl":"/audio/ep1/s04-plain-06.m4a","durationSec":2.93},{"id":"s04-plain-07","speaker":"sancho","text":"Friend, remember that one for his tombstone. Meanwhile I''m down to half a loaf, and I''m guarding it like a castle under siege.","audioUrl":"/audio/ep1/s04-plain-07.m4a","durationSec":8.62}]'::jsonb, '{"id":"s04-plain-bridge","speaker":"sancho","text":"Stay beside me, friend. I''ll call you when something shows up on the horizon.","audioUrl":"/audio/ep1/s04-plain-bridge.m4a","durationSec":5.58}'::jsonb) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's05-windmills-sighted', 5, 'core', 'Giants on the horizon', 'rising', 62, true, array['s04-plain'], 'CP2', null, null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"s05-windmills-sighted-01","speaker":"sancho","text":"Friend. Look at the ridge ahead of you. Thirty or forty windmills, tall as churches, their big wooden sails turning slowly against the sky.","audioUrl":"/audio/ep1/s05-windmills-sighted-01.m4a","durationSec":9.55},{"id":"s05-windmills-sighted-02","speaker":"sancho","text":"Perfectly normal countryside. Except my master has just seen them.","audioUrl":"/audio/ep1/s05-windmills-sighted-02.m4a","durationSec":5.16},{"id":"s05-windmills-sighted-03","speaker":"quixote","text":"Sancho.","audioUrl":"/audio/ep1/s05-windmills-sighted-03.m4a","durationSec":0.71},{"id":"s05-windmills-sighted-04","speaker":"sancho","text":"Oh, no.","audioUrl":"/audio/ep1/s05-windmills-sighted-04.m4a","durationSec":1.2},{"id":"s05-windmills-sighted-05","speaker":"quixote","text":"Do you see them?","audioUrl":"/audio/ep1/s05-windmills-sighted-05.m4a","durationSec":0.94},{"id":"s05-windmills-sighted-06","speaker":"sancho","text":"Yes.","audioUrl":"/audio/ep1/s05-windmills-sighted-06.m4a","durationSec":0.81},{"id":"s05-windmills-sighted-07","speaker":"quixote","text":"Giants.","audioUrl":"/audio/ep1/s05-windmills-sighted-07.m4a","durationSec":0.73},{"id":"s05-windmills-sighted-08","speaker":"sancho","text":"Windmills.","audioUrl":"/audio/ep1/s05-windmills-sighted-08.m4a","durationSec":1.09},{"id":"s05-windmills-sighted-09","speaker":"quixote","text":"Thirty giants! Maybe forty, maybe a thousand, I did not count, and every one with arms two leagues long!","audioUrl":"/audio/ep1/s05-windmills-sighted-09.m4a","durationSec":7.28},{"id":"s05-windmills-sighted-10","speaker":"sancho","text":"Master, those are sails. The wind turns them, and they grind flour for bread. You like bread.","audioUrl":"/audio/ep1/s05-windmills-sighted-10.m4a","durationSec":6.93},{"id":"s05-windmills-sighted-11","speaker":"quixote","text":"Bread? Destiny stands on that ridge, and you speak to me of bread?","audioUrl":"/audio/ep1/s05-windmills-sighted-11.m4a","durationSec":4.11},{"id":"s05-windmills-sighted-12","speaker":"sancho","text":"It is very good bread. Friend, that ridge is more bread than I have seen in my whole life.","audioUrl":"/audio/ep1/s05-windmills-sighted-12.m4a","durationSec":6.03},{"id":"s05-windmills-sighted-13","speaker":"quixote","text":"Fortune is arranging our affairs better than we could have wished. This is righteous war, Sancho.","audioUrl":"/audio/ep1/s05-windmills-sighted-13.m4a","durationSec":5.73},{"id":"s05-windmills-sighted-14","speaker":"sancho","text":"So, he says giants, I say windmills. Friend, you have the deciding vote, and I know which way you''re leaning.","audioUrl":"/audio/ep1/s05-windmills-sighted-14.m4a","durationSec":7.76}]'::jsonb, '{"id":"s05-windmills-sighted-bridge","speaker":"sancho","text":"Stay close, friend. He''s sizing them up; I''ll call you when he picks one.","audioUrl":"/audio/ep1/s05-windmills-sighted-bridge.m4a","durationSec":5.77}'::jsonb) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's06-the-one-on-the-left', 6, 'optional', 'The one on the left', 'rising', 46, false, array['s05-windmills-sighted'], null, null, null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"s06-the-one-on-the-left-01","speaker":"sancho","text":"The windmills are closer now. You can hear them creak, a long wooden groan, and each sail''s shadow sweeps across the road like the hand of a clock.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-01.m4a","durationSec":9.17},{"id":"s06-the-one-on-the-left-02","speaker":"quixote","text":"Sancho. The one on the left.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-02.m4a","durationSec":2.02},{"id":"s06-the-one-on-the-left-03","speaker":"sancho","text":"The windmill?","audioUrl":"/audio/ep1/s06-the-one-on-the-left-03.m4a","durationSec":1.07},{"id":"s06-the-one-on-the-left-04","speaker":"quixote","text":"The giant. He has been watching us.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-04.m4a","durationSec":2.32},{"id":"s06-the-one-on-the-left-05","speaker":"sancho","text":"He has no eyes.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-05.m4a","durationSec":1.49},{"id":"s06-the-one-on-the-left-06","speaker":"quixote","text":"Precisely... A professional.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-06.m4a","durationSec":1.88},{"id":"s06-the-one-on-the-left-07","speaker":"sancho","text":"Friend, are you still with me? Good. One of us should be.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-07.m4a","durationSec":4.46},{"id":"s06-the-one-on-the-left-08","speaker":"quixote","text":"Look! He waves his arms. He is challenging me.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-08.m4a","durationSec":3.46},{"id":"s06-the-one-on-the-left-09","speaker":"sancho","text":"That''s the wind, master.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-09.m4a","durationSec":1.9},{"id":"s06-the-one-on-the-left-10","speaker":"quixote","text":"And why is the wind blowing?","audioUrl":"/audio/ep1/s06-the-one-on-the-left-10.m4a","durationSec":1.42},{"id":"s06-the-one-on-the-left-11","speaker":"sancho","text":"Because... huh. Actually, I don''t know.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-11.m4a","durationSec":3.61},{"id":"s06-the-one-on-the-left-12","speaker":"quixote","text":"Ha! Even you admit there is a mystery.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-12.m4a","durationSec":2.5},{"id":"s06-the-one-on-the-left-13","speaker":"sancho","text":"He won... he actually won one. Friend, never tell him; I need a bite of bread to recover.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-13.m4a","durationSec":6.88}]'::jsonb, '{"id":"s06-the-one-on-the-left-bridge","speaker":"sancho","text":"I have one more question for him; I''ll call you before he does anything expensive.","audioUrl":"/audio/ep1/s06-the-one-on-the-left-bridge.m4a","durationSec":5.31}'::jsonb) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's07-who-pays', 7, 'optional', 'Who pays for a windmill', 'rising', 38, false, array['s05-windmills-sighted'], null, null, null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"s07-who-pays-01","speaker":"sancho","text":"Ahead of you the sails turn and turn. My master is polishing his lance with his sleeve, and that is never a good sign.","audioUrl":"/audio/ep1/s07-who-pays-01.m4a","durationSec":7.74},{"id":"s07-who-pays-02","speaker":"sancho","text":"Master, before you attack. If you knock one down, who pays for the windmill?","audioUrl":"/audio/ep1/s07-who-pays-02.m4a","durationSec":5.45},{"id":"s07-who-pays-03","speaker":"quixote","text":"The king.","audioUrl":"/audio/ep1/s07-who-pays-03.m4a","durationSec":0.57},{"id":"s07-who-pays-04","speaker":"sancho","text":"Which king?","audioUrl":"/audio/ep1/s07-who-pays-04.m4a","durationSec":1.05},{"id":"s07-who-pays-05","speaker":"quixote","text":"We will discuss that after the battle.","audioUrl":"/audio/ep1/s07-who-pays-05.m4a","durationSec":1.95},{"id":"s07-who-pays-06","speaker":"sancho","text":"And the flour? That mill grinds bread for half the valley. Knock it down and everyone eats soup.","audioUrl":"/audio/ep1/s07-who-pays-06.m4a","durationSec":6.43},{"id":"s07-who-pays-07","speaker":"quixote","text":"Then the giant has stolen their bread, and I shall win it back for them.","audioUrl":"/audio/ep1/s07-who-pays-07.m4a","durationSec":3.75},{"id":"s07-who-pays-08","speaker":"sancho","text":"Hm, that almost made sense. Friend, for half a second I agreed with him. Please don''t let it happen again.","audioUrl":"/audio/ep1/s07-who-pays-08.m4a","durationSec":8.33}]'::jsonb, '{"id":"s07-who-pays-bridge","speaker":"sancho","text":"He''s gathering up his reins. Stay beside me, friend; I''ll call you when he''s ready.","audioUrl":"/audio/ep1/s07-who-pays-bridge.m4a","durationSec":6.14}'::jsonb) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's08-lance-in-rest', 8, 'core', 'Lance in rest', 'rising', 55, true, array['s05-windmills-sighted'], 'CP3', null, null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"s08-lance-in-rest-01","speaker":"sancho","text":"You are facing the windmills now. My master sits tall on Rocinante, his buckler braced on his arm, his lance in rest, pointed at the nearest sail.","audioUrl":"/audio/ep1/s08-lance-in-rest-01.m4a","durationSec":9.9},{"id":"s08-lance-in-rest-02","speaker":"quixote","text":"If you are afraid, Sancho, go aside and say your prayers, while I meet them in fierce and unequal combat.","audioUrl":"/audio/ep1/s08-lance-in-rest-02.m4a","durationSec":6.52},{"id":"s08-lance-in-rest-03","speaker":"sancho","text":"I''m not afraid, I''m right, and that''s different. Friend, back me up here.","audioUrl":"/audio/ep1/s08-lance-in-rest-03.m4a","durationSec":5.52},{"id":"s08-lance-in-rest-04","speaker":"quixote","text":"Do not flee, you cowards! It is one knight alone who comes against you.","audioUrl":"/audio/ep1/s08-lance-in-rest-04.m4a","durationSec":4.73},{"id":"s08-lance-in-rest-05","speaker":"sancho","text":"Nobody is fleeing, master. They''re bolted to the ground.","audioUrl":"/audio/ep1/s08-lance-in-rest-05.m4a","durationSec":4.17},{"id":"s08-lance-in-rest-06","speaker":"quixote","text":"Lady Dulcinea, flower of beauty, I commend myself to you. Stand by me in this peril.","audioUrl":"/audio/ep1/s08-lance-in-rest-06.m4a","durationSec":5.98},{"id":"s08-lance-in-rest-07","speaker":"sancho","text":"He''s talking to his lady. She''s far away in Toboso, but he says she hears every word.","audioUrl":"/audio/ep1/s08-lance-in-rest-07.m4a","durationSec":6.19},{"id":"s08-lance-in-rest-08","speaker":"sancho","text":"Friend, stay with me. Whatever those things are, we watch together. I''m holding the last of the bread, in case anyone needs comfort.","audioUrl":"/audio/ep1/s08-lance-in-rest-08.m4a","durationSec":9.04}]'::jsonb, '{"id":"s08-lance-in-rest-bridge","speaker":"sancho","text":"He''s ready. Stay with me, friend; I''ll call you the moment Rocinante moves.","audioUrl":"/audio/ep1/s08-lance-in-rest-bridge.m4a","durationSec":5.92}'::jsonb) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's09-charge', 9, 'climax', 'The charge', 'climax', 50, true, array['s08-lance-in-rest'], null, null, 'charge', 'Ormsby 1885, Part I, ch. VIII', '[{"id":"s09-charge-01","speaker":"sancho","text":"Ahead of you, my master spurs Rocinante, and the old horse lowers his head and heads straight for the nearest windmill.","audioUrl":"/audio/ep1/s09-charge-01.m4a","durationSec":7.26},{"id":"s09-charge-02","speaker":"sancho","text":"Rocinante breaks into a gallop. Ride with him if your legs feel good, or stay right here beside me. Either way, we see it together.","audioUrl":"/audio/ep1/s09-charge-02.m4a","durationSec":9.12},{"id":"s09-charge-03","speaker":"quixote","text":"Wave all the arms you like, giant! For Dulcinea! You shall answer to me!","audioUrl":"/audio/ep1/s09-charge-03.m4a","durationSec":4.81},{"id":"s09-charge-04","speaker":"sancho","text":"Master, it''s a windmill! It''s a windmill!","audioUrl":"/audio/ep1/s09-charge-04.m4a","durationSec":3.18},{"id":"s09-charge-05","speaker":"sancho","text":"Just then the wind picks up. The great sail swings down, and the lance goes straight into it.","audioUrl":"/audio/ep1/s09-charge-05.m4a","durationSec":6.14},{"id":"s09-charge-06","speaker":"sancho","text":"Crack. The lance shatters into pieces. The sail sweeps horse and rider up and drops them, rolling over and over across the plain.","audioUrl":"/audio/ep1/s09-charge-06.m4a","durationSec":8.73},{"id":"s09-charge-07","speaker":"quixote","text":"A worthy opponent...","audioUrl":"/audio/ep1/s09-charge-07.m4a","durationSec":1.08},{"id":"s09-charge-08","speaker":"sancho","text":"Hold on, master, I''m coming! Friend, come with me. That was the expensive part.","audioUrl":"/audio/ep1/s09-charge-08.m4a","durationSec":6.7}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 's10-aftermath', 10, 'ending', 'Freston the enchanter', 'epilogue', 46, true, array['s09-charge'], null, null, null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"s10-aftermath-01","speaker":"sancho","text":"Dust settles around you. My master lies flat beside Rocinante, and I come bouncing up on my donkey.","audioUrl":"/audio/ep1/s10-aftermath-01.m4a","durationSec":7.47},{"id":"s10-aftermath-02","speaker":"sancho","text":"God help us, master. Didn''t I tell you they were windmills? Nobody could miss it, unless he had windmills in his head.","audioUrl":"/audio/ep1/s10-aftermath-02.m4a","durationSec":8.01},{"id":"s10-aftermath-03","speaker":"quixote","text":"Hush, friend Sancho. The sage Freston turned the giants into mills, to rob me of the glory of defeating them.","audioUrl":"/audio/ep1/s10-aftermath-03.m4a","durationSec":7},{"id":"s10-aftermath-04","speaker":"sancho","text":"Of course. Freston. The enchanter nobody has ever seen.","audioUrl":"/audio/ep1/s10-aftermath-04.m4a","durationSec":4.7},{"id":"s10-aftermath-05","speaker":"quixote","text":"His arts will fail in the end. Help me up; we ride for Puerto Lapice, where adventures are thick on the road.","audioUrl":"/audio/ep1/s10-aftermath-05.m4a","durationSec":6.68},{"id":"s10-aftermath-06","speaker":"sancho","text":"And bread, I hope. Friend, from now on I only eat bread that was never a giant. Thank you for riding with us, second squire, go well.","audioUrl":"/audio/ep1/s10-aftermath-06.m4a","durationSec":10.08}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'e01-encourage', 11, 'optional', 'A knight''s companion', 'rising', 6, false, '{}', null, null, 'encourage', 'Ormsby 1885, Part I, ch. VII-VIII', '[{"id":"e01-encourage-01","speaker":"quixote","text":"Second squire, a knight is only as brave as the friend who rides beside him. I am glad it is you.","audioUrl":"/audio/ep1/e01-encourage-01.m4a","durationSec":5.9}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'e02-encourage', 12, 'optional', 'Good company', 'rising', 9, false, '{}', null, null, 'encourage', 'Ormsby 1885, Part I, ch. VII-VIII', '[{"id":"e02-encourage-01","speaker":"sancho","text":"Friend, between you and me, this is the nicest part of the trip. Open road, good company, and nobody attacking anything.","audioUrl":"/audio/ep1/e02-encourage-01.m4a","durationSec":8.73}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'e03-encourage', 13, 'optional', 'Better shared', 'rising', 7, false, '{}', null, null, 'encourage', 'Ormsby 1885, Part I, ch. VII-VIII', '[{"id":"e03-encourage-01","speaker":"quixote","text":"Stay beside me, friend. Every road is better shared.","audioUrl":"/audio/ep1/e03-encourage-01.m4a","durationSec":3.72},{"id":"e03-encourage-02","speaker":"sancho","text":"That''s the wisest thing he''s said all week.","audioUrl":"/audio/ep1/e03-encourage-02.m4a","durationSec":2.67}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'e04-encourage', 14, 'optional', 'Best conversation', 'rising', 10, false, '{}', null, null, 'encourage', 'Ormsby 1885, Part I, ch. VII-VIII', '[{"id":"e04-encourage-01","speaker":"sancho","text":"Still with us, friend? Good. My master talks to the sky, my donkey talks to nobody, so you''re the best company on this road.","audioUrl":"/audio/ep1/e04-encourage-01.m4a","durationSec":9.18}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'x01-signoff', 15, 'signoff', 'Until next time', 'epilogue', 25, false, '{}', null, null, null, 'Ormsby 1885, Part I, ch. VII-VIII', '[{"id":"x01-signoff-01","speaker":"sancho","text":"Heading home, friend? That''s fine, good thinking even. The windmills aren''t going anywhere.","audioUrl":"/audio/ep1/x01-signoff-01.m4a","durationSec":6.75},{"id":"x01-signoff-02","speaker":"quixote","text":"A wise squire knows when the day''s road is done. Our quest will wait, exactly where we leave it.","audioUrl":"/audio/ep1/x01-signoff-02.m4a","durationSec":5.61},{"id":"x01-signoff-03","speaker":"sancho","text":"I''ll save your place, and I''ll save you some bread. Some of the bread. Come back whenever you like.","audioUrl":"/audio/ep1/x01-signoff-03.m4a","durationSec":6.96},{"id":"x01-signoff-04","speaker":"quixote","text":"Farewell for now, second squire. Go in peace; our road will be here.","audioUrl":"/audio/ep1/x01-signoff-04.m4a","durationSec":4.64}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'r01-recap-cp1', 16, 'recap', 'Previously: the departure', 'warmup', 28, false, '{}', null, 'CP1', null, 'Ormsby 1885, Part I, ch. VII', '[{"id":"r01-recap-cp1-01","speaker":"quixote","text":"Previously, my second squire, we rode out of the village at dawn to right the wrongs of the world.","audioUrl":"/audio/ep1/r01-recap-cp1-01.m4a","durationSec":5.43},{"id":"r01-recap-cp1-02","speaker":"sancho","text":"And I came along on my donkey, with saddlebags, a wine-skin, and the promise of an island.","audioUrl":"/audio/ep1/r01-recap-cp1-02.m4a","durationSec":6.27},{"id":"r01-recap-cp1-03","speaker":"quixote","text":"No one saw us leave. Not one wrong in all the world suspects we are coming.","audioUrl":"/audio/ep1/r01-recap-cp1-03.m4a","durationSec":4.45},{"id":"r01-recap-cp1-04","speaker":"sancho","text":"Not my wife, either. Friend, welcome back: the road is open, the bread is packed, and my master is already looking for trouble. Stay beside me.","audioUrl":"/audio/ep1/r01-recap-cp1-04.m4a","durationSec":10.54}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'r02-recap-cp2', 17, 'recap', 'Previously: giants sighted', 'warmup', 29, false, '{}', null, 'CP2', null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"r02-recap-cp2-01","speaker":"quixote","text":"Previously, on the plain of Montiel, we sighted thirty or forty giants on the horizon.","audioUrl":"/audio/ep1/r02-recap-cp2-01.m4a","durationSec":5.28},{"id":"r02-recap-cp2-02","speaker":"sancho","text":"Windmills. He says giants, I say windmills, and they grind flour for bread.","audioUrl":"/audio/ep1/r02-recap-cp2-02.m4a","durationSec":5.89},{"id":"r02-recap-cp2-03","speaker":"quixote","text":"Monstrous giants, with arms two leagues long. Fortune itself has placed them in my path, squire.","audioUrl":"/audio/ep1/r02-recap-cp2-03.m4a","durationSec":6.39},{"id":"r02-recap-cp2-04","speaker":"sancho","text":"Fortune placed them on a ridge, where the wind is. Friend, welcome back: the windmills are right where we left them, still turning, and still not giants.","audioUrl":"/audio/ep1/r02-recap-cp2-04.m4a","durationSec":10.06}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'r03-recap-cp3', 18, 'recap', 'Previously: facing the windmills', 'warmup', 28, false, '{}', null, 'CP3', null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"r03-recap-cp3-01","speaker":"quixote","text":"Previously, I faced the giants with my lance in rest, and commended myself to my lady Dulcinea.","audioUrl":"/audio/ep1/r03-recap-cp3-01.m4a","durationSec":6.15},{"id":"r03-recap-cp3-02","speaker":"sancho","text":"I told him they were windmills. He told me to go and pray if I was afraid.","audioUrl":"/audio/ep1/r03-recap-cp3-02.m4a","durationSec":5.15},{"id":"r03-recap-cp3-03","speaker":"quixote","text":"A squire''s fear is natural. A knight''s courage is not for sale.","audioUrl":"/audio/ep1/r03-recap-cp3-03.m4a","durationSec":3.74},{"id":"r03-recap-cp3-04","speaker":"sancho","text":"Neither is my bread, and there is very little left. Friend, welcome back: he''s still sitting on Rocinante, still pointing his lance at a windmill. Stay beside me.","audioUrl":"/audio/ep1/r03-recap-cp3-04.m4a","durationSec":11.84}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'c01-finish-cp1', 19, 'compressed_ending', 'The story, quickly, from the departure', 'epilogue', 46, false, '{}', null, 'CP1', null, 'Ormsby 1885, Part I, ch. VII-VIII', '[{"id":"c01-finish-cp1-01","speaker":"sancho","text":"Here''s the rest of the story, friend, told quickly. We ride out onto the plain of Montiel, and there on the ridge stand thirty or forty windmills.","audioUrl":"/audio/ep1/c01-finish-cp1-01.m4a","durationSec":9.69},{"id":"c01-finish-cp1-02","speaker":"quixote","text":"Giants, Sancho! Monstrous giants! If you are afraid, go aside and pray.","audioUrl":"/audio/ep1/c01-finish-cp1-02.m4a","durationSec":5.81},{"id":"c01-finish-cp1-03","speaker":"sancho","text":"He commends himself to his lady Dulcinea, lowers his lance, and charges. The wind turns a sail, the lance shatters, and horse and rider roll across the plain.","audioUrl":"/audio/ep1/c01-finish-cp1-03.m4a","durationSec":10.72},{"id":"c01-finish-cp1-04","speaker":"sancho","text":"I rush to help him. Didn''t I tell you they were windmills, master?","audioUrl":"/audio/ep1/c01-finish-cp1-04.m4a","durationSec":4.41},{"id":"c01-finish-cp1-05","speaker":"quixote","text":"The sage Freston turned the giants into mills, to rob me of my glory. On to Puerto Lapice!","audioUrl":"/audio/ep1/c01-finish-cp1-05.m4a","durationSec":5.86},{"id":"c01-finish-cp1-06","speaker":"sancho","text":"So we ride on, one lance lighter, and my bread is still safe. Thank you for riding with us, friend. Go well.","audioUrl":"/audio/ep1/c01-finish-cp1-06.m4a","durationSec":7.98}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'c02-finish-cp2', 20, 'compressed_ending', 'The story, quickly, from the windmills', 'epilogue', 47, false, '{}', null, 'CP2', null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"c02-finish-cp2-01","speaker":"sancho","text":"Here''s how it ends, friend, told quickly. The windmills turn on the ridge, and my master is certain they are giants.","audioUrl":"/audio/ep1/c02-finish-cp2-01.m4a","durationSec":8.13},{"id":"c02-finish-cp2-02","speaker":"quixote","text":"If you are afraid, Sancho, go aside and say your prayers. I fight them alone.","audioUrl":"/audio/ep1/c02-finish-cp2-02.m4a","durationSec":5.2},{"id":"c02-finish-cp2-03","speaker":"sancho","text":"He commends himself to Dulcinea, braces his buckler, and charges on Rocinante. A sail catches the lance, it shatters, and horse and rider go rolling across the plain.","audioUrl":"/audio/ep1/c02-finish-cp2-03.m4a","durationSec":11.63},{"id":"c02-finish-cp2-04","speaker":"sancho","text":"I come running on my donkey to help him up. I did say windmills.","audioUrl":"/audio/ep1/c02-finish-cp2-04.m4a","durationSec":4.7},{"id":"c02-finish-cp2-05","speaker":"quixote","text":"The enchanter Freston changed them into mills, to steal my glory. His tricks will fail. We ride for Puerto Lapice.","audioUrl":"/audio/ep1/c02-finish-cp2-05.m4a","durationSec":7.46},{"id":"c02-finish-cp2-06","speaker":"sancho","text":"And so we ride on, bruised but cheerful, with a little bread left. Thank you, second squire. Go well.","audioUrl":"/audio/ep1/c02-finish-cp2-06.m4a","durationSec":7.52}]'::jsonb, null) on conflict (episode_id, id) do nothing;
insert into public.scenes (episode_id, id, position, type, title, part, duration_sec, required, prerequisites, checkpoint, for_checkpoint, beat, source, lines, bridge) values ('ep1', 'c03-finish-cp3', 21, 'compressed_ending', 'The story, quickly, from the charge', 'epilogue', 42, false, '{}', null, 'CP3', null, 'Ormsby 1885, Part I, ch. VIII', '[{"id":"c03-finish-cp3-01","speaker":"sancho","text":"Here''s how it ends, friend, told quickly. My master spurs Rocinante straight at the nearest windmill, shouting for Dulcinea.","audioUrl":"/audio/ep1/c03-finish-cp3-01.m4a","durationSec":8.99},{"id":"c03-finish-cp3-02","speaker":"sancho","text":"The wind swings a sail down. The lance shatters, and the sail flings horse and rider rolling across the plain.","audioUrl":"/audio/ep1/c03-finish-cp3-02.m4a","durationSec":7.17},{"id":"c03-finish-cp3-03","speaker":"sancho","text":"I come running on my donkey. Master, didn''t I tell you they were windmills?","audioUrl":"/audio/ep1/c03-finish-cp3-03.m4a","durationSec":5.04},{"id":"c03-finish-cp3-04","speaker":"quixote","text":"Hush, Sancho. The sage Freston turned those giants into mills, to rob me of my glory. But his arts will fail against my good sword.","audioUrl":"/audio/ep1/c03-finish-cp3-04.m4a","durationSec":8.64},{"id":"c03-finish-cp3-05","speaker":"sancho","text":"So I help him up, and we ride on toward Puerto Lapice. He''s sore, I''m hungry, and the bread survived. Thank you for riding with us, friend.","audioUrl":"/audio/ep1/c03-finish-cp3-05.m4a","durationSec":10.17}]'::jsonb, null) on conflict (episode_id, id) do nothing;
